select public.upsert_bank_question($json${"id":"evan-easy-001","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Em que cidade nasceu Jesus?","bible_ref":"Mateus 2:1","verse_text":"E sendo Jesus já nascido em Belém da Judeia, nos dias do rei Herodes, eis que vieram uns magos do oriente a Jerusalém,"},"fr":{"prompt":"Dans quelle ville Jésus est-il né ?","bible_ref":"Matthieu 2:1","verse_text":"Jésus étant né à Bethléhem en Judée, au temps du roi Hérode, voici des mages d’Orient arrivèrent à Jérusalem,"},"en":{"prompt":"In which town was Jesus born?","bible_ref":"Matthew 2:1","verse_text":"Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,"},"es":{"prompt":"¿En qué ciudad nació Jesús?","bible_ref":"Mateo 2:1","verse_text":"Y COMO fué nacido Jesús en Bethlehem de Judea en días del rey Herodes, he aquí unos magos vinieron del oriente á Jerusalem,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Belém"},"fr":{"text":"Bethléhem"},"en":{"text":"Bethlehem"},"es":{"text":"Bethlehem"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nazaré"},"fr":{"text":"Nazareth"},"en":{"text":"Nazareth"},"es":{"text":"Nazaret"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jerusalém"},"fr":{"text":"Jérusalem"},"en":{"text":"Jerusalem"},"es":{"text":"Jerusalem"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cafarnaum"},"fr":{"text":"Capernaüm"},"en":{"text":"Capernaum"},"es":{"text":"Capernaum"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-002","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":2,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Onde foi deitado o menino Jesus quando nasceu?","bible_ref":"Lucas 2:7","verse_text":"E deu à luz seu filho primogênito, e o envolveu em panos, e o deitou numa manjedoura; porque não havia lugar para eles na hospedaria."},"fr":{"prompt":"Où l’enfant Jésus fut-il couché à sa naissance ?","bible_ref":"Luc 2:7","verse_text":"et elle enfanta son fils premier-né. Elle l’emmaillota, et le coucha dans une crèche, parce qu’il n’y avait pas de place pour eux dans l’hôtellerie."},"en":{"prompt":"Where was baby Jesus laid when he was born?","bible_ref":"Luke 2:7","verse_text":"And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn."},"es":{"prompt":"¿Dónde acostaron al niño Jesús cuando nació?","bible_ref":"Lucas 2:7","verse_text":"Y parió á su hijo primogénito, y le envolvió en pañales, y acostóle en un pesebre, porque no había lugar para ellos en el mesón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Numa manjedoura"},"fr":{"text":"Dans une crèche"},"en":{"text":"In a manger"},"es":{"text":"En un pesebre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Num berço de ouro"},"fr":{"text":"Dans un berceau d’or"},"en":{"text":"In a golden cradle"},"es":{"text":"En una cuna de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Numa cama da hospedaria"},"fr":{"text":"Dans un lit de l’hôtellerie"},"en":{"text":"In a bed at the inn"},"es":{"text":"En una cama del mesón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Num barco"},"fr":{"text":"Dans une barque"},"en":{"text":"In a boat"},"es":{"text":"En un barco"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-003","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":3,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Quando Jesus foi batizado, o Espírito de Deus desceu como uma ave. Que ave?","bible_ref":"Mateus 3:16","verse_text":"E tendo Jesus sido batizado, subiu logo da água. E eis que os céus se lhe abriram, e ele viu o Espírito de Deus descendo como uma pomba, vindo sobre ele."},"fr":{"prompt":"Quand Jésus fut baptisé, l’Esprit de Dieu descendit comme un oiseau. Lequel ?","bible_ref":"Matthieu 3:16","verse_text":"Dès que Jésus eut été baptisé, il sortit de l’eau. Et voici, les cieux s’ouvrirent, et il vit l’Esprit de Dieu descendre comme une colombe et venir sur lui."},"en":{"prompt":"When Jesus was baptized, the Spirit of God came down like a bird. Which bird?","bible_ref":"Matthew 3:16","verse_text":"And Jesus, when he was baptized, went up straightway out of the water: and, lo, the heavens were opened unto him, and he saw the Spirit of God descending like a dove, and lighting upon him:"},"es":{"prompt":"Cuando Jesús fue bautizado, el Espíritu de Dios descendió como un ave. ¿Qué ave?","bible_ref":"Mateo 3:16","verse_text":"Y Jesús, después que fué bautizado, subió luego del agua; y he aquí los cielos le fueron abiertos, y vió al Espíritu de Dios que descendía como paloma, y venía sobre él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma pomba"},"fr":{"text":"Une colombe"},"en":{"text":"A dove"},"es":{"text":"Una paloma"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma águia"},"fr":{"text":"Un aigle"},"en":{"text":"An eagle"},"es":{"text":"Un águila"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um corvo"},"fr":{"text":"Un corbeau"},"en":{"text":"A raven"},"es":{"text":"Un cuervo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um pardal"},"fr":{"text":"Un passereau"},"en":{"text":"A sparrow"},"es":{"text":"Un gorrión"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-004","type":"choice","level":"easy","testament":"nt","book":"MRK","chapter":1,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Quem batizou Jesus no rio Jordão?","bible_ref":"Marcos 1:9","verse_text":"E aconteceu que, naqueles dias, Jesus de Nazaré da Galileia veio, e foi batizado por João no Jordão."},"fr":{"prompt":"Qui a baptisé Jésus dans le Jourdain ?","bible_ref":"Marc 1:9","verse_text":"En ce temps-là, Jésus vint de Nazareth en Galilée, et il fut baptisé par Jean dans le Jourdain."},"en":{"prompt":"Who baptized Jesus in the Jordan?","bible_ref":"Mark 1:9","verse_text":"And it came to pass in those days, that Jesus came from Nazareth of Galilee, and was baptized of John in Jordan."},"es":{"prompt":"¿Quién bautizó a Jesús en el Jordán?","bible_ref":"Marcos 1:9","verse_text":"Y aconteció en aquellos días, que Jesús vino de Nazaret de Galilea, y fué bautizado por Juan en el Jordán."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"João"},"fr":{"text":"Jean"},"en":{"text":"John"},"es":{"text":"Juan"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pedro"},"fr":{"text":"Pierre"},"en":{"text":"Peter"},"es":{"text":"Pedro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Paulo"},"fr":{"text":"Paul"},"en":{"text":"Paul"},"es":{"text":"Pablo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-005","type":"choice","level":"easy","testament":"nt","book":"JHN","chapter":2,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Numa festa de casamento, Jesus transformou a água em quê?","bible_ref":"João 2:9","verse_text":"E quando o mestre de cerimônia experimentou a água feita vinho (sem saber de onde era, porém os serventes que haviam tirado a água sabiam), o mestre de cerimônia chamou o noivo,"},"fr":{"prompt":"Lors d’un repas de noces, Jésus changea l’eau en quoi ?","bible_ref":"Jean 2:9","verse_text":"Quand l’ordonnateur du repas eut goûté l’eau changée en vin, ne sachant d’où venait ce vin, tandis que les serviteurs, qui avaient puisé l’eau, le savaient bien, il appela l’époux,"},"en":{"prompt":"At a wedding feast, what did Jesus turn the water into?","bible_ref":"John 2:9","verse_text":"When the ruler of the feast had tasted the water that was made wine, and knew not whence it was: (but the servants which drew the water knew;) the governor of the feast called the bridegroom,"},"es":{"prompt":"En una boda, ¿en qué convirtió Jesús el agua?","bible_ref":"Juan 2:9","verse_text":"Y como el maestresala gustó el agua hecha vino, que no sabía de dónde era (mas lo sabían los sirvientes que habían sacado el agua), el maestresala llama al esposo,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Vinho"},"fr":{"text":"Vin"},"en":{"text":"Wine"},"es":{"text":"Vino"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Leite"},"fr":{"text":"Lait"},"en":{"text":"Milk"},"es":{"text":"Leche"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Azeite"},"fr":{"text":"Huile"},"en":{"text":"Oil"},"es":{"text":"Aceite"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mel"},"fr":{"text":"Miel"},"en":{"text":"Honey"},"es":{"text":"Miel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-006","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":14,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Para alimentar a multidão, havia ali dois peixes e quantos pães?","bible_ref":"Mateus 14:17","verse_text":"E eles lhe disseram: Nada temos aqui além de cinco pães e dois peixes."},"fr":{"prompt":"Pour nourrir la foule, il y avait là deux poissons et combien de pains ?","bible_ref":"Matthieu 14:17","verse_text":"Mais ils lui dirent: Nous n’avons ici que cinq pains et deux poissons."},"en":{"prompt":"To feed the crowd, there were two fishes and how many loaves?","bible_ref":"Matthew 14:17","verse_text":"And they say unto him, We have here but five loaves, and two fishes."},"es":{"prompt":"Para alimentar a la multitud, había allí dos peces y ¿cuántos panes?","bible_ref":"Mateo 14:17","verse_text":"Y ellos dijeron: No tenemos aquí sino cinco panes y dos peces."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cinco"},"fr":{"text":"Cinq"},"en":{"text":"Five"},"es":{"text":"Cinco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-007","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":14,"verse_start":25,"verse_end":25,"texts":{"pt":{"prompt":"De noite, Jesus foi ter com os discípulos andando sobre o quê?","bible_ref":"Mateus 14:25","verse_text":"Mas à quarta vigília da noite Jesus foi até eles, andando sobre o mar."},"fr":{"prompt":"La nuit, Jésus alla vers ses disciples en marchant sur quoi ?","bible_ref":"Matthieu 14:25","verse_text":"A la quatrième veille de la nuit, Jésus alla vers eux, marchant sur la mer."},"en":{"prompt":"At night, Jesus went to the disciples walking on what?","bible_ref":"Matthew 14:25","verse_text":"And in the fourth watch of the night Jesus went unto them, walking on the sea."},"es":{"prompt":"De noche, Jesús fue hacia los discípulos. ¿Sobre qué andaba?","bible_ref":"Mateo 14:25","verse_text":"Mas á la cuarta vela de la noche, Jesús fué á ellos andando sobre la mar."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sobre o mar"},"fr":{"text":"Sur la mer"},"en":{"text":"On the sea"},"es":{"text":"Sobre la mar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sobre uma ponte"},"fr":{"text":"Sur un pont"},"en":{"text":"On a bridge"},"es":{"text":"Sobre un puente"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sobre a areia da praia"},"fr":{"text":"Sur le sable de la plage"},"en":{"text":"On the sand of the beach"},"es":{"text":"Sobre la arena de la playa"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sobre um tronco"},"fr":{"text":"Sur un tronc d’arbre"},"en":{"text":"On a log"},"es":{"text":"Sobre un tronco"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-008","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":15,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Na parábola do filho pródigo, quem correu a abraçar o filho quando ele voltou?","bible_ref":"Lucas 15:20","verse_text":"E levantando-se, foi a seu pai. E quando ainda estava longe, o seu pai o viu, e teve compaixão dele; e correndo, caiu ao seu pescoço, e o beijou."},"fr":{"prompt":"Dans la parabole du fils prodigue, qui courut embrasser le fils à son retour ?","bible_ref":"Luc 15:20","verse_text":"Et il se leva, et alla vers son père. Comme il était encore loin, son père le vit et fut ému de compassion, il courut se jeter à son cou et le baisa."},"en":{"prompt":"In the parable of the prodigal son, who ran to hug the son when he came back?","bible_ref":"Luke 15:20","verse_text":"And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him."},"es":{"prompt":"En la parábola del hijo pródigo, ¿quién corrió a abrazar al hijo cuando volvió?","bible_ref":"Lucas 15:20","verse_text":"Y levantándose, vino á su padre. Y como aun estuviese lejos, viólo su padre, y fué movido á misericordia, y corrió, y echóse sobre su cuello, y besóle."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O pai"},"fr":{"text":"Le père"},"en":{"text":"His father"},"es":{"text":"El padre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O irmão mais velho"},"fr":{"text":"Le frère aîné"},"en":{"text":"His elder brother"},"es":{"text":"El hermano mayor"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A mãe"},"fr":{"text":"La mère"},"en":{"text":"His mother"},"es":{"text":"La madre"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um servo"},"fr":{"text":"Un serviteur"},"en":{"text":"A servant"},"es":{"text":"Un siervo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-009","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":10,"verse_start":33,"verse_end":33,"texts":{"pt":{"prompt":"Na parábola de Jesus, quem teve compaixão do homem ferido à beira do caminho?","bible_ref":"Lucas 10:33","verse_text":"Porém um certo samaritano, que ia pelo caminho, veio junto a ele, e vendo-o, teve compaixão dele."},"fr":{"prompt":"Dans la parabole de Jésus, qui fut ému de compassion pour l’homme blessé au bord du chemin ?","bible_ref":"Luc 10:33","verse_text":"Mais un Samaritain, qui voyageait, étant venu là, fut ému de compassion lorsqu’il le vit."},"en":{"prompt":"In Jesus’ parable, who had compassion on the wounded man by the road?","bible_ref":"Luke 10:33","verse_text":"But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him,"},"es":{"prompt":"En la parábola de Jesús, ¿quién tuvo compasión del hombre herido junto al camino?","bible_ref":"Lucas 10:33","verse_text":"Mas un Samaritano que transitaba, viniendo cerca de él, y viéndole, fué movido á misericordia;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um samaritano"},"fr":{"text":"Un Samaritain"},"en":{"text":"A Samaritan"},"es":{"text":"Un samaritano"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um sacerdote"},"fr":{"text":"Un sacrificateur"},"en":{"text":"A priest"},"es":{"text":"Un sacerdote"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um levita"},"fr":{"text":"Un Lévite"},"en":{"text":"A Levite"},"es":{"text":"Un levita"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um soldado romano"},"fr":{"text":"Un soldat romain"},"en":{"text":"A Roman soldier"},"es":{"text":"Un soldado romano"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-010","type":"choice","level":"easy","testament":"nt","book":"LUK","chapter":19,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Zaqueu era baixo. Onde subiu ele para ver Jesus?","bible_ref":"Lucas 19:4","verse_text":"E correndo com antecedência, subiu em uma árvore de frutos que parecem figos, para o ver; porque ele passaria por ali."},"fr":{"prompt":"Zachée était petit. Où monta-t-il pour voir Jésus ?","bible_ref":"Luc 19:4","verse_text":"Il courut en avant, et monta sur un sycomore pour le voir, parce qu’il devait passer par là."},"en":{"prompt":"Zacchæus was short. Where did he climb to see Jesus?","bible_ref":"Luke 19:4","verse_text":"And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way."},"es":{"prompt":"Zaqueo era pequeño. ¿Dónde subió para ver a Jesús?","bible_ref":"Lucas 19:4","verse_text":"Y corriendo delante, subióse á un árbol sicómoro para verle; porque había de pasar por allí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A uma árvore"},"fr":{"text":"Sur un arbre"},"en":{"text":"Up a tree"},"es":{"text":"A un árbol"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ao telhado de uma casa"},"fr":{"text":"Sur le toit d’une maison"},"en":{"text":"Onto a roof"},"es":{"text":"Al tejado de una casa"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A uma torre"},"fr":{"text":"Sur une tour"},"en":{"text":"Up a tower"},"es":{"text":"A una torre"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A um muro"},"fr":{"text":"Sur un mur"},"en":{"text":"Onto a wall"},"es":{"text":"A un muro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-011","type":"choice","level":"easy","testament":"nt","book":"JHN","chapter":11,"verse_start":43,"verse_end":43,"texts":{"pt":{"prompt":"A quem disse Jesus em voz alta: «Sai fora!», à porta do sepulcro?","bible_ref":"João 11:43","verse_text":"E havendo dito isto, clamou com grande voz: Lázaro, sai fora."},"fr":{"prompt":"À qui Jésus cria-t-il « Sors ! » devant le tombeau ?","bible_ref":"Jean 11:43","verse_text":"Ayant dit cela, il cria d’une voix forte: Lazare, sors!"},"en":{"prompt":"To whom did Jesus cry “Come forth!” at the tomb?","bible_ref":"John 11:43","verse_text":"And when he thus had spoken, he cried with a loud voice, Lazarus, come forth."},"es":{"prompt":"¿A quién le dijo Jesús a gran voz «¡Ven fuera!» ante el sepulcro?","bible_ref":"Juan 11:43","verse_text":"Y habiendo dicho estas cosas, clamó á gran voz: Lázaro, ven fuera."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Lázaro"},"fr":{"text":"Lazare"},"en":{"text":"Lazarus"},"es":{"text":"Lázaro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pedro"},"fr":{"text":"Pierre"},"en":{"text":"Peter"},"es":{"text":"Pedro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"José"},"fr":{"text":"Joseph"},"en":{"text":"Joseph"},"es":{"text":"José"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tomé"},"fr":{"text":"Thomas"},"en":{"text":"Thomas"},"es":{"text":"Tomás"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-easy-012","type":"choice","level":"easy","testament":"nt","book":"MAT","chapter":28,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"No sepulcro vazio, o que disse o anjo sobre Jesus?","bible_ref":"Mateus 28:6","verse_text":"Ele não está aqui, pois já ressuscitou, como ele disse. Vinde ver o lugar onde o Senhor jazia."},"fr":{"prompt":"Au tombeau vide, que dit l’ange au sujet de Jésus ?","bible_ref":"Matthieu 28:6","verse_text":"Il n’est point ici; il est ressuscité, comme il l’avait dit. Venez, voyez le lieu où il était couché,"},"en":{"prompt":"At the empty tomb, what did the angel say about Jesus?","bible_ref":"Matthew 28:6","verse_text":"He is not here: for he is risen, as he said. Come, see the place where the Lord lay."},"es":{"prompt":"En el sepulcro vacío, ¿qué dijo el ángel acerca de Jesús?","bible_ref":"Mateo 28:6","verse_text":"No está aquí; porque ha resucitado, como dijo. Venid, ved el lugar donde fué puesto el Señor."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ressuscitou"},"fr":{"text":"Il est ressuscité"},"en":{"text":"He is risen"},"es":{"text":"Ha resucitado"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Está a dormir"},"fr":{"text":"Il dort"},"en":{"text":"He is asleep"},"es":{"text":"Está durmiendo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uns ladrões levaram-no"},"fr":{"text":"Des voleurs l’ont pris"},"en":{"text":"Thieves took him"},"es":{"text":"Unos ladrones se lo llevaron"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Está escondido no jardim"},"fr":{"text":"Il est caché dans le jardin"},"en":{"text":"He is hiding in the garden"},"es":{"text":"Está escondido en el huerto"}}}]}$json$::jsonb);
