select public.upsert_bank_question($json${"id":"evan-medium-001","type":"choice","level":"medium","testament":"nt","book":"LUK","chapter":1,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Que nome disse o anjo que Zacarias devia dar ao filho que Isabel ia ter?","bible_ref":"Lucas 1:13","verse_text":"Mas o anjo lhe disse: Zacarias, não temas, pois a tua oração foi ouvida. E Isabel, tua mulher, dará à luz um filho, e lhe porás o nome de João."},"fr":{"prompt":"Quel nom l’ange dit-il à Zacharie de donner au fils qu’Élisabeth allait avoir ?","bible_ref":"Luc 1:13","verse_text":"Mais l’ange lui dit: Ne crains point, Zacharie; car ta prière a été exaucée. Ta femme Élisabeth t’enfantera un fils, et tu lui donneras le nom de Jean."},"en":{"prompt":"What name did the angel tell Zacharias to give the son Elisabeth would bear?","bible_ref":"Luke 1:13","verse_text":"But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John."},"es":{"prompt":"¿Qué nombre dijo el ángel a Zacarías que pusiera al hijo que Elisabet iba a tener?","bible_ref":"Lucas 1:13","verse_text":"Mas el ángel le dijo: Zacarías, no temas; porque tu oración ha sido oída, y tu mujer Elisabet te parirá un hijo, y llamarás su nombre Juan."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"João"},"fr":{"text":"Jean"},"en":{"text":"John"},"es":{"text":"Juan"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Zacarias"},"fr":{"text":"Zacharie"},"en":{"text":"Zacharias"},"es":{"text":"Zacarías"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Elias"},"fr":{"text":"Élie"},"en":{"text":"Elias"},"es":{"text":"Elías"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-002","type":"choice","level":"medium","testament":"nt","book":"MAT","chapter":26,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Quanto deram os chefes dos sacerdotes a Judas para entregar Jesus?","bible_ref":"Mateus 26:15","verse_text":"e disse: O que quereis me dar, para que eu o entregue a vós? E eles lhe determinaram trinta moedas de prata."},"fr":{"prompt":"Combien les principaux sacrificateurs payèrent-ils Judas pour livrer Jésus ?","bible_ref":"Matthieu 26:15","verse_text":"et dit: Que voulez-vous me donner, et je vous le livrerai? Et ils lui payèrent trente pièces d’argent."},"en":{"prompt":"How much did the chief priests give Judas to betray Jesus?","bible_ref":"Matthew 26:15","verse_text":"And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver."},"es":{"prompt":"¿Cuánto le dieron a Judas los príncipes de los sacerdotes por entregar a Jesús?","bible_ref":"Mateo 26:15","verse_text":"Y les dijo: ¿Qué me queréis dar, y yo os lo entregaré? Y ellos le señalaron treinta piezas de plata."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Trinta moedas de prata"},"fr":{"text":"Trente pièces d’argent"},"en":{"text":"Thirty pieces of silver"},"es":{"text":"Treinta piezas de plata"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dez moedas de prata"},"fr":{"text":"Dix pièces d’argent"},"en":{"text":"Ten pieces of silver"},"es":{"text":"Diez piezas de plata"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Vinte moedas de prata"},"fr":{"text":"Vingt pièces d’argent"},"en":{"text":"Twenty pieces of silver"},"es":{"text":"Veinte piezas de plata"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cinquenta moedas de ouro"},"fr":{"text":"Cinquante pièces d’or"},"en":{"text":"Fifty pieces of gold"},"es":{"text":"Cincuenta piezas de oro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-003","type":"choice","level":"medium","testament":"nt","book":"MAT","chapter":14,"verse_start":29,"verse_end":29,"texts":{"pt":{"prompt":"Que discípulo desceu do barco e andou sobre as águas para ir ter com Jesus?","bible_ref":"Mateus 14:29","verse_text":"E ele disse: Vem. Então Pedro desceu do barco e andou sobre as águas, para vir em direção a Jesus."},"fr":{"prompt":"Quel disciple sortit de la barque et marcha sur les eaux pour aller vers Jésus ?","bible_ref":"Matthieu 14:29","verse_text":"Et il dit: Viens! Pierre sortit de la barque, et marcha sur les eaux, pour aller vers Jésus."},"en":{"prompt":"Which disciple came down out of the ship and walked on the water to go to Jesus?","bible_ref":"Matthew 14:29","verse_text":"And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus."},"es":{"prompt":"¿Qué discípulo descendió del barco y anduvo sobre las aguas para ir a Jesús?","bible_ref":"Mateo 14:29","verse_text":"Y él dijo: Ven. Y descendiendo Pedro del barco, andaba sobre las aguas para ir á Jesús."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Pedro"},"fr":{"text":"Pierre"},"en":{"text":"Peter"},"es":{"text":"Pedro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"João"},"fr":{"text":"Jean"},"en":{"text":"John"},"es":{"text":"Juan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"André"},"fr":{"text":"André"},"en":{"text":"Andrew"},"es":{"text":"Andrés"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tiago"},"fr":{"text":"Jacques"},"en":{"text":"James"},"es":{"text":"Jacobo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-004","type":"choice","level":"medium","testament":"nt","book":"MRK","chapter":5,"verse_start":42,"verse_end":42,"texts":{"pt":{"prompt":"Que idade tinha a filha de Jairo quando Jesus a fez levantar-se?","bible_ref":"Marcos 5:42","verse_text":"E logo a menina se levantou e andou, pois já tinha doze anos de idade. E ficaram grandemente espantados."},"fr":{"prompt":"Quel âge avait la fille de Jaïrus quand Jésus la fit se lever ?","bible_ref":"Marc 5:42","verse_text":"Aussitôt la jeune fille se leva, et se mit à marcher; car elle avait douze ans. Et ils furent dans un grand étonnement."},"en":{"prompt":"How old was the daughter of Jairus when Jesus raised her up?","bible_ref":"Mark 5:42","verse_text":"And straightway the damsel arose, and walked; for she was of the age of twelve years. And they were astonished with a great astonishment."},"es":{"prompt":"¿Qué edad tenía la hija de Jairo cuando Jesús la levantó?","bible_ref":"Marcos 5:42","verse_text":"Y luego la muchacha se levantó, y andaba; porque tenía doce años. Y se espantaron de grande espanto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Doze anos"},"fr":{"text":"Douze ans"},"en":{"text":"Twelve years"},"es":{"text":"Doce años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três anos"},"fr":{"text":"Trois ans"},"en":{"text":"Three years"},"es":{"text":"Tres años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete anos"},"fr":{"text":"Sept ans"},"en":{"text":"Seven years"},"es":{"text":"Siete años"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dezoito anos"},"fr":{"text":"Dix-huit ans"},"en":{"text":"Eighteen years"},"es":{"text":"Dieciocho años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-005","type":"choice","level":"medium","testament":"nt","book":"LUK","chapter":19,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Qual era o trabalho de Zaqueu, em Jericó?","bible_ref":"Lucas 19:2","verse_text":"E eis que havia ali um homem, chamado pelo nome de Zaqueu, e este era chefe dos publicanos, e era rico."},"fr":{"prompt":"Quel était le métier de Zachée, à Jéricho ?","bible_ref":"Luc 19:2","verse_text":"Et voici, un homme riche, appelé Zachée, chef des publicains, cherchait à voir qui était Jésus;"},"en":{"prompt":"What was Zacchæus’ job in Jericho?","bible_ref":"Luke 19:2","verse_text":"And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich."},"es":{"prompt":"¿Cuál era el oficio de Zaqueo, en Jericó?","bible_ref":"Lucas 19:2","verse_text":"Y he aquí un varón llamado Zaqueo, el cual era el principal de los publicanos, y era rico;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Chefe dos publicanos"},"fr":{"text":"Chef des publicains"},"en":{"text":"Chief among the publicans"},"es":{"text":"Principal de los publicanos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pescador"},"fr":{"text":"Pêcheur"},"en":{"text":"Fisherman"},"es":{"text":"Pescador"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sacerdote do templo"},"fr":{"text":"Sacrificateur du temple"},"en":{"text":"Priest in the temple"},"es":{"text":"Sacerdote del templo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Centurião romano"},"fr":{"text":"Centenier romain"},"en":{"text":"Roman centurion"},"es":{"text":"Centurión romano"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-006","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":3,"verse_start":1,"verse_end":2,"texts":{"pt":{"prompt":"Que fariseu, chefe dos judeus, foi ter com Jesus de noite?","bible_ref":"João 3:1-2","verse_text":"E havia um homem dos fariseus, cujo nome era Nicodemos, chefe dos judeus. Este veio a Jesus de noite, e disse-lhe: Rabi, bem sabemos que és Mestre vindo de Deus; porque ninguém pode fazer estes sinais que tu fazes, se Deus não for com ele."},"fr":{"prompt":"Quel pharisien, chef des Juifs, vint auprès de Jésus de nuit ?","bible_ref":"Jean 3:1-2","verse_text":"Mais il y eut un homme d’entre les pharisiens, nommé Nicodème, un chef des Juifs, qui vint, lui, auprès de Jésus, de nuit, et lui dit: Rabbi, nous savons que tu es un docteur venu de Dieu; car personne ne peut faire ces miracles que tu fais, si Dieu n’est avec lui."},"en":{"prompt":"Which Pharisee, a ruler of the Jews, came to Jesus by night?","bible_ref":"John 3:1-2","verse_text":"There was a man of the Pharisees, named Nicodemus, a ruler of the Jews: The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him."},"es":{"prompt":"¿Qué fariseo, príncipe de los judíos, vino a Jesús de noche?","bible_ref":"Juan 3:1-2","verse_text":"Y HABÍA un hombre de los Fariseos que se llamaba Nicodemo, príncipe de los Judíos. Este vino á Jesús de noche, y díjole: Rabbí, sabemos que has venido de Dios por maestro; porque nadie puede hacer estas señales que tú haces, si no fuere Dios con él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nicodemos"},"fr":{"text":"Nicodème"},"en":{"text":"Nicodemus"},"es":{"text":"Nicodemo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Gamaliel"},"fr":{"text":"Gamaliel"},"en":{"text":"Gamaliel"},"es":{"text":"Gamaliel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Caifás"},"fr":{"text":"Caïphe"},"en":{"text":"Caiaphas"},"es":{"text":"Caifás"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Zaqueu"},"fr":{"text":"Zachée"},"en":{"text":"Zacchæus"},"es":{"text":"Zaqueo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-007","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":4,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Junto ao poço, o que pediu Jesus à mulher de Samaria?","bible_ref":"João 4:7","verse_text":"Veio uma mulher de Samaria para tirar água; Disse-lhe Jesus: Dá-me de beber."},"fr":{"prompt":"Près du puits, que demanda Jésus à la femme de Samarie ?","bible_ref":"Jean 4:7","verse_text":"Une femme de Samarie vint puiser de l’eau. Jésus lui dit: Donne-moi à boire."},"en":{"prompt":"At the well, what did Jesus ask the woman of Samaria?","bible_ref":"John 4:7","verse_text":"There cometh a woman of Samaria to draw water: Jesus saith unto her, Give me to drink."},"es":{"prompt":"Junto al pozo, ¿qué le pidió Jesús a la mujer de Samaria?","bible_ref":"Juan 4:7","verse_text":"Vino una mujer de Samaria á sacar agua: y Jesús le dice: Dame de beber."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Que lhe desse de beber"},"fr":{"text":"De lui donner à boire"},"en":{"text":"To give him a drink"},"es":{"text":"Que le diera de beber"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Que lhe desse pão"},"fr":{"text":"De lui donner du pain"},"en":{"text":"To give him bread"},"es":{"text":"Que le diera pan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Que lhe lavasse os pés"},"fr":{"text":"De lui laver les pieds"},"en":{"text":"To wash his feet"},"es":{"text":"Que le lavara los pies"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Que lhe mostrasse o caminho"},"fr":{"text":"De lui montrer le chemin"},"en":{"text":"To show him the way"},"es":{"text":"Que le mostrara el camino"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-008","type":"choice","level":"medium","testament":"nt","book":"JHN","chapter":11,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Em que aldeia viviam Lázaro e as suas irmãs Maria e Marta?","bible_ref":"João 11:1","verse_text":"E estava doente um certo Lázaro, de Betânia, a aldeia de Maria e de sua irmã Marta."},"fr":{"prompt":"Dans quel village vivaient Lazare et ses sœurs Marie et Marthe ?","bible_ref":"Jean 11:1","verse_text":"Il y avait un homme malade, Lazare, de Béthanie, village de Marie et de Marthe, sa sœur."},"en":{"prompt":"In which town did Lazarus and his sisters Mary and Martha live?","bible_ref":"John 11:1","verse_text":"Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha."},"es":{"prompt":"¿En qué aldea vivían Lázaro y sus hermanas María y Marta?","bible_ref":"Juan 11:1","verse_text":"ESTABA entonces enfermo uno llamado Lázaro, de Bethania, la aldea de María y de Marta su hermana."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Betânia"},"fr":{"text":"Béthanie"},"en":{"text":"Bethany"},"es":{"text":"Bethania"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Betsaida"},"fr":{"text":"Bethsaïda"},"en":{"text":"Bethsaida"},"es":{"text":"Bethsaida"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Caná"},"fr":{"text":"Cana"},"en":{"text":"Cana"},"es":{"text":"Caná"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Naim"},"fr":{"text":"Naïn"},"en":{"text":"Nain"},"es":{"text":"Naín"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-009","type":"choice","level":"medium","testament":"nt","book":"MRK","chapter":2,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Como chegaram os amigos do paralítico até Jesus, por causa da multidão?","bible_ref":"Marcos 2:4","verse_text":"Como não podiam se aproximar dele por causa da multidão, descobriram o telhado onde ele estava, fizeram um buraco, e baixaram por ele o leito em que jazia o paralítico."},"fr":{"prompt":"Comment les amis du paralytique arrivèrent-ils jusqu’à Jésus, à cause de la foule ?","bible_ref":"Marc 2:4","verse_text":"Comme ils ne pouvaient l’aborder, à cause de la foule, ils découvrirent le toit de la maison où il était, et ils descendirent par cette ouverture le lit sur lequel le paralytique était couché."},"en":{"prompt":"How did the friends of the man sick of the palsy reach Jesus, because of the crowd?","bible_ref":"Mark 2:4","verse_text":"And when they could not come nigh unto him for the press, they uncovered the roof where he was: and when they had broken it up, they let down the bed wherein the sick of the palsy lay."},"es":{"prompt":"¿Cómo llegaron hasta Jesús los amigos del paralítico, a causa del gentío?","bible_ref":"Marcos 2:4","verse_text":"Y como no podían llegar á él á causa del gentío, descubrieron el techo de donde estaba, y haciendo abertura, bajaron el lecho en que yacía el paralítico."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Desceram-no pelo telhado"},"fr":{"text":"Ils le descendirent par le toit"},"en":{"text":"They let him down through the roof"},"es":{"text":"Lo bajaron por el techo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Passaram-no por uma janela"},"fr":{"text":"Ils le passèrent par une fenêtre"},"en":{"text":"They passed him through a window"},"es":{"text":"Lo pasaron por una ventana"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Levaram-no num barco"},"fr":{"text":"Ils l’amenèrent en barque"},"en":{"text":"They brought him by boat"},"es":{"text":"Lo llevaron en un barco"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Entraram pela porta das traseiras"},"fr":{"text":"Ils entrèrent par la porte de derrière"},"en":{"text":"They came in by the back door"},"es":{"text":"Entraron por la puerta de atrás"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-010","type":"choice","level":"medium","testament":"nt","book":"MRK","chapter":15,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Quem foi obrigado a levar a cruz de Jesus quando vinha do campo?","bible_ref":"Marcos 15:21","verse_text":"E forçaram um Simão cireneu, que estava passando, vindo do campo, o pai de Alexandre e de Rufo, para que levasse sua cruz."},"fr":{"prompt":"Qui fut forcé de porter la croix de Jésus en revenant des champs ?","bible_ref":"Marc 15:21","verse_text":"Ils forcèrent à porter la croix de Jésus un passant qui revenait des champs, Simon de Cyrène, père d’Alexandre et de Rufus;"},"en":{"prompt":"Who was compelled to bear Jesus’ cross as he came out of the country?","bible_ref":"Mark 15:21","verse_text":"And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross."},"es":{"prompt":"¿A quién obligaron a llevar la cruz de Jesús cuando venía del campo?","bible_ref":"Marcos 15:21","verse_text":"Y cargaron á uno que pasaba, Simón Cireneo, padre de Alejandro y de Rufo, que venía del campo, para que llevase su cruz."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Simão, o cireneu"},"fr":{"text":"Simon de Cyrène"},"en":{"text":"Simon, a Cyrenian"},"es":{"text":"Simón Cireneo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"José de Arimateia"},"fr":{"text":"Joseph d’Arimathée"},"en":{"text":"Joseph of Arimathæa"},"es":{"text":"José de Arimatea"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Barrabás"},"fr":{"text":"Barabbas"},"en":{"text":"Barabbas"},"es":{"text":"Barrabás"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Simão Pedro"},"fr":{"text":"Simon Pierre"},"en":{"text":"Simon Peter"},"es":{"text":"Simón Pedro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-011","type":"choice","level":"medium","testament":"nt","book":"MAT","chapter":2,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Em sonho, para onde mandou o anjo José fugir com o menino e a sua mãe?","bible_ref":"Mateus 2:13","verse_text":"E tendo eles partido, eis que um anjo do Senhor apareceu a José em sonho, dizendo: Levanta-te, toma o menino e sua mãe, e foge para o Egito; e fica lá até que eu te diga, porque Herodes buscará o menino para o matar."},"fr":{"prompt":"En songe, où l’ange dit-il à Joseph de fuir avec l’enfant et sa mère ?","bible_ref":"Matthieu 2:13","verse_text":"Lorsqu’ils furent partis, voici, un ange du Seigneur apparut en songe à Joseph, et dit: Lève-toi, prends le petit enfant et sa mère, fuis en Égypte, et restes-y jusqu’à ce que je te parle; car Hérode cherchera le petit enfant pour le faire périr."},"en":{"prompt":"In a dream, where did the angel tell Joseph to flee with the young child and his mother?","bible_ref":"Matthew 2:13","verse_text":"And when they were departed, behold, the angel of the Lord appeareth to Joseph in a dream, saying, Arise, and take the young child and his mother, and flee into Egypt, and be thou there until I bring thee word: for Herod will seek the young child to destroy him."},"es":{"prompt":"En sueños, ¿adónde mandó el ángel a José huir con el niño y su madre?","bible_ref":"Mateo 2:13","verse_text":"Y partidos ellos, he aquí el ángel del Señor aparece en sueños á José, diciendo: Levántate, y toma al niño y á su madre, y huye á Egipto, y estáte allá hasta que yo te lo diga; porque ha de acontecer, que Herodes buscará al niño para matarlo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Para o Egito"},"fr":{"text":"En Égypte"},"en":{"text":"Into Egypt"},"es":{"text":"A Egipto"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Para Nazaré"},"fr":{"text":"À Nazareth"},"en":{"text":"To Nazareth"},"es":{"text":"A Nazaret"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Para a Samaria"},"fr":{"text":"En Samarie"},"en":{"text":"To Samaria"},"es":{"text":"A Samaria"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Para Cafarnaum"},"fr":{"text":"À Capernaüm"},"en":{"text":"To Capernaum"},"es":{"text":"A Capernaum"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-012","type":"choice","level":"medium","testament":"nt","book":"LUK","chapter":17,"verse_start":15,"verse_end":16,"texts":{"pt":{"prompt":"Jesus curou dez leprosos. Quantos voltaram para lhe agradecer?","bible_ref":"Lucas 17:15-16","verse_text":"E vendo um deles que estava são, voltou, glorificando a Deus a alta voz. E caiu com o rosto a seus pés, agradecendo-lhe; e este era samaritano."},"fr":{"prompt":"Jésus guérit dix lépreux. Combien revinrent lui rendre grâces ?","bible_ref":"Luc 17:15-16","verse_text":"L’un d’eux, se voyant guéri, revint sur ses pas, glorifiant Dieu à haute voix. Il tomba sur sa face aux pieds de Jésus, et lui rendit grâces. C’était un Samaritain."},"en":{"prompt":"Jesus healed ten lepers. How many came back to give him thanks?","bible_ref":"Luke 17:15-16","verse_text":"And one of them, when he saw that he was healed, turned back, and with a loud voice glorified God, And fell down on his face at his feet, giving him thanks: and he was a Samaritan."},"es":{"prompt":"Jesús sanó a diez leprosos. ¿Cuántos volvieron a darle gracias?","bible_ref":"Lucas 17:15-16","verse_text":"Entonces uno de ellos, como se vió que estaba limpio, volvió, glorificando á Dios á gran voz; Y derribóse sobre el rostro á sus pies, dándole gracias: y éste era Samaritano."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um, que era samaritano"},"fr":{"text":"Un seul, un Samaritain"},"en":{"text":"One, a Samaritan"},"es":{"text":"Uno, que era samaritano"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Todos os dez"},"fr":{"text":"Tous les dix"},"en":{"text":"All ten"},"es":{"text":"Los diez"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Nove"},"fr":{"text":"Neuf"},"en":{"text":"Nine"},"es":{"text":"Nueve"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dois"},"fr":{"text":"Deux"},"en":{"text":"Two"},"es":{"text":"Dos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-medium-013","type":"order","level":"medium","testament":"nt","book":"MRK","chapter":11,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Ordena estes episódios do Evangelho de Marcos pela ordem em que aparecem.","bible_ref":"Marcos 11:7","verse_text":null},"fr":{"prompt":"Mets ces épisodes de l’Évangile de Marc dans l’ordre où ils apparaissent.","bible_ref":"Marc 11:7","verse_text":null},"en":{"prompt":"Put these episodes from Mark in the order they appear.","bible_ref":"Mark 11:7","verse_text":null},"es":{"prompt":"Ordena estos episodios de Marcos según aparecen.","bible_ref":"Marcos 11:7","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Jesus entra em Jerusalém num jumentinho","ref":"Marcos 11:7"},"fr":{"text":"Jésus entre à Jérusalem sur un ânon","ref":"Marc 11:7"},"en":{"text":"Jesus rides a colt into Jerusalem","ref":"Mark 11:7"},"es":{"text":"Jesús entra en Jerusalem en un pollino","ref":"Marcos 11:7"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jesus expulsa os vendedores do templo","ref":"Marcos 11:15"},"fr":{"text":"Jésus chasse les vendeurs du temple","ref":"Marc 11:15"},"en":{"text":"Jesus casts the sellers out of the temple","ref":"Mark 11:15"},"es":{"text":"Jesús echa a los vendedores del templo","ref":"Marcos 11:15"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jesus diz: «Isto é o meu corpo»","ref":"Marcos 14:22"},"fr":{"text":"Jésus dit : « Ceci est mon corps »","ref":"Marc 14:22"},"en":{"text":"Jesus says, “This is my body”","ref":"Mark 14:22"},"es":{"text":"Jesús dice: «Esto es mi cuerpo»","ref":"Marcos 14:22"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jesus é preso","ref":"Marcos 14:46"},"fr":{"text":"Jésus est saisi","ref":"Marc 14:46"},"en":{"text":"Jesus is taken","ref":"Mark 14:46"},"es":{"text":"Jesús es prendido","ref":"Marcos 14:46"}}}]}$json$::jsonb);
