select public.upsert_bank_question($json${"id":"evan-medium-018","type":"verse","level":"medium","testament":"nt","book":"JHN","chapter":15,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Eu sou a _____, vós sois os ramos; quem está em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer.","bible_ref":"João 15:5","verse_text":"Eu sou a videira, vós sois os ramos; quem está em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer."},"fr":{"prompt":"Je suis le _____, vous êtes les sarments. Celui qui demeure en moi et en qui je demeure porte beaucoup de fruit, car sans moi vous ne pouvez rien faire.","bible_ref":"Jean 15:5","verse_text":"Je suis le cep, vous êtes les sarments. Celui qui demeure en moi et en qui je demeure porte beaucoup de fruit, car sans moi vous ne pouvez rien faire."},"en":{"prompt":"I am the _____, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing.","bible_ref":"John 15:5","verse_text":"I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing."},"es":{"prompt":"Yo soy la _____, vosotros los pámpanos: el que está en mí, y yo en él, éste lleva mucho fruto; porque sin mí nada podéis hacer.","bible_ref":"Juan 15:5","verse_text":"Yo soy la vid, vosotros los pámpanos: el que está en mí, y yo en él, éste lleva mucho fruto; porque sin mí nada podéis hacer."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"azinheira"},"fr":{"text":"chêne"},"en":{"text":"oak tree"},"es":{"text":"encina"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"videira"},"fr":{"text":"cep"},"en":{"text":"vine"},"es":{"text":"vid"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"figueira"},"fr":{"text":"figuier"},"en":{"text":"fig tree"},"es":{"text":"higuera"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"palmeira"},"fr":{"text":"palmi