select public.upsert_bank_question($json${"id":"evan-hard-001","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":21,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Quantos grandes peixes havia na rede que Simão Pedro puxou para terra, depois da ressurreição?","bible_ref":"João 21:11","verse_text":"Simão Pedro subiu, e puxou a rede para a terra, cheia de cento e cinquenta e três grandes peixes; e sendo tantos, a rede não se rompeu."},"fr":{"prompt":"Combien de grands poissons y avait-il dans le filet que Simon Pierre tira à terre, après la résurrection ?","bible_ref":"Jean 21:11","verse_text":"Simon Pierre monta dans la barque, et tira à terre le filet plein de cent cinquante-trois grands poissons; et quoiqu’il y en eût tant, le filet ne se rompit point."},"en":{"prompt":"How many great fishes were in the net Simon Peter drew to land after the resurrection?","bible_ref":"John 21:11","verse_text":"Simon Peter went up, and drew the net to land full of great fishes, an hundred and fifty and three: and for all there were so many, yet was not the net broken."},"es":{"prompt":"¿Cuántos grandes peces había en la red que Simón Pedro trajo a tierra, después de la resurrección?","bible_ref":"Juan 21:11","verse_text":"Subió Simón Pedro, y trajo la red á tierra, llena de grandes peces, ciento cincuenta y tres: y siendo tantos, la red no se rompió."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"153"},"fr":{"text":"153"},"en":{"text":"153"},"es":{"text":"153"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"144"},"fr":{"text":"144"},"en":{"text":"144"},"es":{"text":"144"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"120"},"fr":{"text":"120"},"en":{"text":"120"},"es":{"text":"120"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"99"},"fr":{"text":"99"},"en":{"text":"99"},"es":{"text":"99"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-002","type":"choice","level":"hard","testament":"nt","book":"MAT","chapter":27,"verse_start":33,"verse_end":33,"texts":{"pt":{"prompt":"Segundo Mateus, o que significa o nome «Gólgota»?","bible_ref":"Mateus 27:33","verse_text":"E quando chegaram ao lugar chamado Gólgota, que significa “o lugar da caveira”,"},"fr":{"prompt":"Selon Matthieu, que signifie le nom « Golgotha » ?","bible_ref":"Matthieu 27:33","verse_text":"Arrivés au lieu nommé Golgotha, ce qui signifie lieu du crâne,"},"en":{"prompt":"According to Matthew, what does the name “Golgotha” mean?","bible_ref":"Matthew 27:33","verse_text":"And when they were come unto a place called Golgotha, that is to say, a place of a skull,"},"es":{"prompt":"Según Mateo, ¿qué significa el nombre «Gólgotha»?","bible_ref":"Mateo 27:33","verse_text":"Y como llegaron al lugar que se llama Gólgotha, que es dicho, El lugar de la calavera,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Lugar da caveira"},"fr":{"text":"Lieu du crâne"},"en":{"text":"A place of a skull"},"es":{"text":"El lugar de la calavera"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Casa de misericórdia"},"fr":{"text":"Maison de miséricorde"},"en":{"text":"House of mercy"},"es":{"text":"Casa de misericordia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Monte do sacrifício"},"fr":{"text":"Mont du sacrifice"},"en":{"text":"Mount of sacrifice"},"es":{"text":"Monte del sacrificio"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jardim das oliveiras"},"fr":{"text":"Jardin des oliviers"},"en":{"text":"Garden of olives"},"es":{"text":"Huerto de los olivos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-003","type":"choice","level":"hard","testament":"nt","book":"MRK","chapter":5,"verse_start":41,"verse_end":41,"texts":{"pt":{"prompt":"O que significam as palavras «Talita cumi», ditas por Jesus à filha de Jairo?","bible_ref":"Marcos 5:41","verse_text":"Ele pegou a mão da menina, e lhe disse: “Talita cumi”, (que significa: “Menina, eu te digo, levanta-te”)."},"fr":{"prompt":"Que signifient les mots « Talitha koumi », dits par Jésus à la fille de Jaïrus ?","bible_ref":"Marc 5:41","verse_text":"Il la saisit par la main, et lui dit: Talitha koumi, ce qui signifie: Jeune fille, lève-toi, je te le dis."},"en":{"prompt":"What do the words “Talitha cumi”, spoken by Jesus to the daughter of Jairus, mean?","bible_ref":"Mark 5:41","verse_text":"And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise."},"es":{"prompt":"¿Qué significan las palabras «Talitha cumi», dichas por Jesús a la hija de Jairo?","bible_ref":"Marcos 5:41","verse_text":"Y tomando la mano de la muchacha, le dice: Talitha cumi; que es, si lo interpretares: Muchacha, á ti digo, levántate."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Menina, levanta-te"},"fr":{"text":"Jeune fille, lève-toi"},"en":{"text":"Damsel, arise"},"es":{"text":"Muchacha, levántate"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Abre-te"},"fr":{"text":"Ouvre-toi"},"en":{"text":"Be opened"},"es":{"text":"Sé abierto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Deus meu, porque me desamparaste?"},"fr":{"text":"Mon Dieu, pourquoi m’as-tu abandonné ?"},"en":{"text":"My God, why hast thou forsaken me?"},"es":{"text":"Dios mío, ¿por qué me has desamparado?"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mestre"},"fr":{"text":"Maître"},"en":{"text":"Master"},"es":{"text":"Maestro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-004","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":2,"verse_start":36,"verse_end":36,"texts":{"pt":{"prompt":"De que tribo era a profetisa Ana, filha de Fanuel?","bible_ref":"Lucas 2:36","verse_text":"E estava ali a profetiza Ana, filha de Fanuel, da tribo de Aser. Ela já tinha idade avançada, e havia vivido com o marido sete anos desde sua virgindade."},"fr":{"prompt":"De quelle tribu était la prophétesse Anne, fille de Phanuel ?","bible_ref":"Luc 2:36","verse_text":"Il y avait aussi une prophétesse, Anne, fille de Phanuel, de la tribu d’Aser. Elle était fort avancée en âge, et elle avait vécu sept ans avec son mari depuis sa virginité."},"en":{"prompt":"Of which tribe was Anna the prophetess, the daughter of Phanuel?","bible_ref":"Luke 2:36","verse_text":"And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;"},"es":{"prompt":"¿De qué tribu era la profetisa Ana, hija de Phanuel?","bible_ref":"Lucas 2:36","verse_text":"Estaba también allí Ana, profetisa, hija de Phanuel, de la tribu de Aser; la cual había venido en grande edad, y había vivido con su marido siete años desde su virginidad;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Aser"},"fr":{"text":"Aser"},"en":{"text":"Aser"},"es":{"text":"Aser"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Judá"},"fr":{"text":"Juda"},"en":{"text":"Juda"},"es":{"text":"Judá"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Levi"},"fr":{"text":"Lévi"},"en":{"text":"Levi"},"es":{"text":"Leví"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Benjamim"},"fr":{"text":"Benjamin"},"en":{"text":"Benjamin"},"es":{"text":"Benjamín"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-005","type":"choice","level":"hard","testament":"nt","book":"MRK","chapter":10,"verse_start":46,"verse_end":46,"texts":{"pt":{"prompt":"Segundo Marcos, como se chamava o cego que estava sentado junto ao caminho, à saída de Jericó?","bible_ref":"Marcos 10:46","verse_text":"E vieram a Jericó. E saindo ele, e seus discípulos, e uma grande multidão de Jericó, estava Bartimeu, um cego, filho de Timeu, sentado junto ao caminho."},"fr":{"prompt":"Selon Marc, comment s’appelait l’aveugle assis au bord du chemin, à la sortie de Jéricho ?","bible_ref":"Marc 10:46","verse_text":"Ils arrivèrent à Jéricho. Et, lorsque Jésus en sortit, avec ses disciples et une assez grande foule, le fils de Timée, Bartimée, mendiant aveugle, était assis au bord du chemin."},"en":{"prompt":"According to Mark, what was the name of the blind man sitting by the highway side as Jesus went out of Jericho?","bible_ref":"Mark 10:46","verse_text":"And they came to Jericho: and as he went out of Jericho with his disciples and a great number of people, blind Bartimæus, the son of Timæus, sat by the highway side begging."},"es":{"prompt":"Según Marcos, ¿cómo se llamaba el ciego sentado junto al camino, a la salida de Jericó?","bible_ref":"Marcos 10:46","verse_text":"Entonces vienen á Jericó: y saliendo él de Jericó y sus discípulos y una gran compañía, Bartimeo el ciego, hijo de Timeo, estaba sentado junto al camino mendigando."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Bartimeu"},"fr":{"text":"Bartimée"},"en":{"text":"Bartimæus"},"es":{"text":"Bartimeo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Timeu"},"fr":{"text":"Timée"},"en":{"text":"Timæus"},"es":{"text":"Timeo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jairo"},"fr":{"text":"Jaïrus"},"en":{"text":"Jairus"},"es":{"text":"Jairo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Natanael"},"fr":{"text":"Nathanaël"},"en":{"text":"Nathanael"},"es":{"text":"Natanael"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-006","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":3,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Lucas data o início da pregação de João Batista. Em que ano do império de Tibério César?","bible_ref":"Lucas 3:1","verse_text":"No ano quinze do império de Tibério César, sendo Pôncio Pilatos o governador da Judeia, Herodes tetrarca da Galileia, e seu irmão Filipe o tetrarca da Itureia e da província de Traconites, e Lisânias o tetrarca de Abilene;"},"fr":{"prompt":"Luc date le début de la prédication de Jean-Baptiste. En quelle année du règne de Tibère César ?","bible_ref":"Luc 3:1","verse_text":"La quinzième année du règne de Tibère César, lorsque Ponce Pilate était gouverneur de la Judée, Hérode tétrarque de la Galilée, son frère Philippe tétrarque de l’Iturée et du territoire de la Trachonite, Lysanias tétrarque de l’Abilène,"},"en":{"prompt":"Luke dates the start of John the Baptist’s preaching. In which year of the reign of Tiberius Cæsar?","bible_ref":"Luke 3:1","verse_text":"Now in the fifteenth year of the reign of Tiberius Cæsar, Pontius Pilate being governor of Judæa, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of Ituraea and of the region of Trachonitis, and Lysanias the tetrarch of Abilene,"},"es":{"prompt":"Lucas fecha el comienzo de la predicación de Juan el Bautista. ¿En qué año del imperio de Tiberio César?","bible_ref":"Lucas 3:1","verse_text":"Y EN el año quince del imperio de Tiberio César, siendo gobernador de Judea Poncio Pilato, y Herodes tetrarca de Galilea, y su hermano Felipe tetrarca de Iturea y de la provincia de Traconite, y Lisanias tetrarca de Abilinia,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No décimo quinto"},"fr":{"text":"La quinzième"},"en":{"text":"The fifteenth"},"es":{"text":"El decimoquinto"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No décimo segundo"},"fr":{"text":"La douzième"},"en":{"text":"The twelfth"},"es":{"text":"El duodécimo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No trigésimo"},"fr":{"text":"La trentième"},"en":{"text":"The thirtieth"},"es":{"text":"El trigésimo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No terceiro"},"fr":{"text":"La troisième"},"en":{"text":"The third"},"es":{"text":"El tercero"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-007","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":18,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Como se chamava o servo do sumo sacerdote a quem Simão Pedro cortou a orelha direita?","bible_ref":"João 18:10","verse_text":"Simão Pedro, pois, que tinha espada, puxou dela, e feriu ao servo do sacerdote, e cortou a sua orelha direita. E era o nome do servo Malco."},"fr":{"prompt":"Comment s’appelait le serviteur du souverain sacrificateur dont Simon Pierre coupa l’oreille droite ?","bible_ref":"Jean 18:10","verse_text":"Simon Pierre, qui avait une épée, la tira, frappa le serviteur du souverain sacrificateur, et lui coupa l’oreille droite. Ce serviteur s’appelait Malchus."},"en":{"prompt":"What was the name of the high priest’s servant whose right ear Simon Peter cut off?","bible_ref":"John 18:10","verse_text":"Then Simon Peter having a sword drew it, and smote the high priest’s servant, and cut off his right ear. The servant’s name was Malchus."},"es":{"prompt":"¿Cómo se llamaba el siervo del pontífice al que Simón Pedro cortó la oreja derecha?","bible_ref":"Juan 18:10","verse_text":"Entonces Simón Pedro, que tenía espada, sacóla, é hirió al siervo del pontífice, y le cortó la oreja derecha. Y el siervo se llamaba Malco."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Malco"},"fr":{"text":"Malchus"},"en":{"text":"Malchus"},"es":{"text":"Malco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Barrabás"},"fr":{"text":"Barabbas"},"en":{"text":"Barabbas"},"es":{"text":"Barrabás"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Caifás"},"fr":{"text":"Caïphe"},"en":{"text":"Caiaphas"},"es":{"text":"Caifás"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Rufo"},"fr":{"text":"Rufus"},"en":{"text":"Rufus"},"es":{"text":"Rufo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-008","type":"choice","level":"hard","testament":"nt","book":"MAT","chapter":15,"verse_start":37,"verse_end":38,"texts":{"pt":{"prompt":"Numa das multiplicações dos pães sobraram sete cestos cheios. Quantos homens comeram, sem contar mulheres e crianças?","bible_ref":"Mateus 15:37-38","verse_text":"E todos comeram e se saciaram; e levantaram dos pedaços que sobraram sete cestos cheios. E foram os que comeram quatro mil homens, sem contar as mulheres e as crianças."},"fr":{"prompt":"Lors d’une multiplication des pains, il resta sept corbeilles pleines. Combien d’hommes avaient mangé, sans compter les femmes et les enfants ?","bible_ref":"Matthieu 15:37-38","verse_text":"Tous mangèrent et furent rassasiés, et l’on emporta sept corbeilles pleines des morceaux qui restaient. Ceux qui avaient mangé étaient quatre mille hommes, sans les femmes et les enfants."},"en":{"prompt":"At one feeding of the crowd, seven baskets full were left over. How many men had eaten, beside women and children?","bible_ref":"Matthew 15:37-38","verse_text":"And they did all eat, and were filled: and they took up of the broken meat that was left seven baskets full. And they that did eat were four thousand men, beside women and children."},"es":{"prompt":"En una multiplicación de los panes sobraron siete espuertas llenas. ¿Cuántos hombres comieron, sin contar mujeres y niños?","bible_ref":"Mateo 15:37-38","verse_text":"Y comieron todos, y se hartaron: y alzaron lo que sobró de los pedazos, siete espuertas llenas. Y eran los que habían comido, cuatro mil hombres, sin las mujeres y los niños."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"4000"},"fr":{"text":"4000"},"en":{"text":"4000"},"es":{"text":"4000"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"5000"},"fr":{"text":"5000"},"en":{"text":"5000"},"es":{"text":"5000"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"3000"},"fr":{"text":"3000"},"en":{"text":"3000"},"es":{"text":"3000"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"7000"},"fr":{"text":"7000"},"en":{"text":"7000"},"es":{"text":"7000"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-009","type":"choice","level":"hard","testament":"nt","book":"JHN","chapter":5,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Há quantos anos estava doente o homem que Jesus curou junto ao tanque de Betesda?","bible_ref":"João 5:5","verse_text":"E estava ali um certo homem, que havia trinta e oito anos que estava enfermo."},"fr":{"prompt":"Depuis combien d’années était malade l’homme que Jésus guérit près de la piscine de Béthesda ?","bible_ref":"Jean 5:5","verse_text":"Là se trouvait un homme malade depuis trente-huit ans."},"en":{"prompt":"For how many years had the man Jesus healed at the pool of Bethesda had his infirmity?","bible_ref":"John 5:5","verse_text":"And a certain man was there, which had an infirmity thirty and eight years."},"es":{"prompt":"¿Cuántos años llevaba enfermo el hombre que Jesús sanó junto al estanque de Bethesda?","bible_ref":"Juan 5:5","verse_text":"Y estaba allí un hombre que había treinta y ocho años que estaba enfermo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"38 anos"},"fr":{"text":"38 ans"},"en":{"text":"38 years"},"es":{"text":"38 años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"12 anos"},"fr":{"text":"12 ans"},"en":{"text":"12 years"},"es":{"text":"12 años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"18 anos"},"fr":{"text":"18 ans"},"en":{"text":"18 years"},"es":{"text":"18 años"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"40 anos"},"fr":{"text":"40 ans"},"en":{"text":"40 years"},"es":{"text":"40 años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-010","type":"choice","level":"hard","testament":"nt","book":"MRK","chapter":2,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Em Marcos, Jesus chama o cobrador de impostos Levi. De quem era ele filho?","bible_ref":"Marcos 2:14","verse_text":"E enquanto passava, ele viu Levi, filho de Alfeu, sentado no posto de coleta de impostos, e disse-lhe: Segue-me. Então Levi se levantou e o seguiu."},"fr":{"prompt":"Dans Marc, Jésus appelle le péager Lévi. De qui était-il le fils ?","bible_ref":"Marc 2:14","verse_text":"En passant, il vit Lévi, fils d’Alphée, assis au bureau des péages. Il lui dit: Suis-moi. Lévi se leva, et le suivit."},"en":{"prompt":"In Mark, Jesus calls Levi at the receipt of custom. Whose son was he?","bible_ref":"Mark 2:14","verse_text":"And as he passed by, he saw Levi the son of Alphæus sitting at the receipt of custom, and said unto him, Follow me. And he arose and followed him."},"es":{"prompt":"En Marcos, Jesús llama al publicano Leví. ¿De quién era hijo?","bible_ref":"Marcos 2:14","verse_text":"Y pasando, vió á Leví, hijo de Alfeo, sentado al banco de los públicos tributos, y le dice: Sígueme. Y levantándose le siguió."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Alfeu"},"fr":{"text":"Alphée"},"en":{"text":"Alphæus"},"es":{"text":"Alfeo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Zebedeu"},"fr":{"text":"Zébédée"},"en":{"text":"Zebedee"},"es":{"text":"Zebedeo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jonas"},"fr":{"text":"Jonas"},"en":{"text":"Jona"},"es":{"text":"Jonás"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Zacarias"},"fr":{"text":"Zacharie"},"en":{"text":"Zacharias"},"es":{"text":"Zacarías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"evan-hard-011","type":"choice","level":"hard","testament":"nt","book":"LUK","chapter":24,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"A caminho de Emaús, como se chamava um dos dois discípulos que falaram com Jesus?","bible_ref":"Lucas 24:18","verse_text":"E um deles, cujo nome era Cleofas, respondendo-o, disse-lhe: És tu o único viajante em Jerusalém que não sabe as coisas que nela tem acontecido nestes dias?"},"fr":{"prompt":"Sur le chemin d’Émmaüs, comment s’appelait l’un des deux disciples qui parlèrent avec Jésus ?","bible_ref":"Luc 24:18","verse_text":"L’un d’eux, nommé Cléopas, lui répondit: Es-tu le seul qui, séjournant à Jérusalem ne sache pas ce qui y est arrivé ces jours-ci?"},"en":{"prompt":"On the road to Emmaus, what was the name of one of the two disciples who talked with Jesus?","bible_ref":"Luke 24:18","verse_text":"And the one of them, whose name was Cleopas, answering said unto him, Art thou only a stranger in Jerusalem, and hast not known the things which are come to pass there in these days?"},"es":{"prompt":"Camino de Emmaús, ¿cómo se llamaba uno de los dos discípulos que hablaron con Jesús?","bible_ref":"Lucas 24:18","verse_text":"Y respondiendo el uno, que se llamaba Cleofas, le dijo: ¿Tú sólo peregrino eres en Jerusalem, y no has sabido las cosas que en ella han acontecido estos días?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cleofas"},"fr":{"text":"Cléopas"},"en":{"text":"Cleopas"},"es":{"text":"Cleofas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nicodemos"},"fr":{"text":"Nicodème"},"en":{"text":"Nicodemus"},"es":{"text":"Nicodemo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Zaqueu"},"fr":{"text":"Zachée"},"en":{"text":"Zacchæus"},"es":{"text":"Zaqueo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lázaro"},"fr":{"text":"Lazare"},"en":{"text":"Lazarus"},"es":{"text":"Lázaro"}}}]}$json$::jsonb);
